"Fuchsia Very Dark","color_hex":"#46052D","purchase_url":"https://www.breibrink.nl/dmc-35.html"}]$catalog_rows$::jsonb) AS entry(
  catalog_id text,
  number text,
  color_name text,
  color_hex char(7),
  purchase_url text
)
ON CONFLICT (snapshot_id, catalog_id) DO UPDATE
SET
  number = EXCLUDED.number,
  color_name = EXCLUDED.color_name,
  color_hex = EXCLUDED.color_hex,
  purchase_url = EXCLUDED.purchase_url;

DO $verify$
DECLARE
  stored_count integer;
BEGIN
  SELECT count(*)::integer
  INTO stored_count
  FROM floss_catalog_entries AS entries
  JOIN floss_catalog_snapshots AS snapshots ON snapshots.id = entries.snapshot_id
  WHERE snapshots.content_sha256 = 'd3158f96acf96e764615710349b27f70c3cad46c485798890c31369c23e59ab9';

  IF stored_count <> 489 THEN
    RAISE EXCEPTION 'Floss catalog import count mismatch: expected 489, got %', stored_count;
  END IF;
END
$verify$;
